    CHANNEL_OPERATION_BUSY: 'Outra operação deste canal ainda está em andamento. Aguarde e atualize a lista.',
    GENERATION_CONFLICT: 'O canal mudou em outra sessão. Atualize a lista antes de continuar.',
  };
  if (typeof code === 'string' && mensagens[code]) return mensagens[code];
  return 'Não foi possível concluir esta etapa. Atualize a lista e tente novamente quando o estado estiver confirmado.';
}

export function motivoCapacidade(reason: string): string {
  const motivos: Record<string, string> = {
    NOT_CONFIGURED: 'Esta modalidade ainda não está configurada nesta instalação.',
    PARTIAL_CONFIGURATION: 'A configuração Meta está incompleta. Peça ao administrador da instalação para concluí-la.',
    CREDENTIAL_ENCRYPTION_UNAVAILABLE: 'O armazenamento seguro de credenciais não está configurado. Peça ao administrador da instalação para habilitá-lo.',
    MODULE_NOT_CONTRACTED: 'O módulo não oficial não está contratado para esta Mantenedora.',
    AVAILABLE: 'Disponível',
  };
  return motivos[reason] ?? 'Esta modalidade está indisponível. Peça ao administrador da instalação para verificar a configuração.';
}
import { TentativaNumero } from './cadastroNumero';

export type OperacaoCadastro = 'reserva' | 'retomada' | 'autorizacao' | 'confirmacao' | 'acao' | 'pareamento' | 'verificacao' | 'opcoes';
export interface TokenOperacaoCadastro {
  readonly lifecycle: number;
  readonly sequence: number;
  readonly kind: OperacaoCadastro;
  readonly attemptId: string | null;
  readonly targetBuId?: string;
  readonly targetChannelId?: string;
}
export interface TokenLeituraTentativa {
  readonly lifecycle: number;
  readonly attemptId: string;
  readonly channelId: string | null;
  readonly generation: number;
}

/** Owns the single UI operation and monotonically commits server attempt DTOs. */
export class DonoCicloCadastro {
  private lifecycle = 0;
  private sequence = 0;
  private operation: TokenOperacaoCadastro | null = null;
  private current: TentativaNumero | null = null;

  invalidar(clearAttempt = true): number {
    this.lifecycle += 1;
    this.operation = null;
    if (clearAttempt) this.current = null;
    return this.lifecycle;
  }

  atual(): TentativaNumero | null { return this.current; }
  ciclo(): number { return this.lifecycle; }

  iniciar(kind: OperacaoCadastro, attemptId: string | null = this.current?.id ?? null): TokenOperacaoCadastro | null {
    if (this.operation) return null;
    if (attemptId && this.current?.id !== attemptId && kind !== 'retomada') return null;
    const token: TokenOperacaoCadastro = { lifecycle: this.lifecycle, sequence: ++this.sequence, kind, attemptId };
    this.operation = token;
    return token;
  }

  iniciarPareamento(buId: string, channelId: string | null): TokenOperacaoCadastro | null {
    if (this.operation) return null;
    const token: TokenOperacaoCadastro = {
      lifecycle: this.lifecycle, sequence: ++this.sequence, kind: 'pareamento', attemptId: null,
      targetBuId: buId, targetChannelId: channelId ?? undefined,
    };
    this.operation = token;
    return token;
  }

  possui(token: TokenOperacaoCadastro): boolean {
    return this.operation === token && token.lifecycle === this.lifecycle;
  }

  finalizar(token: TokenOperacaoCadastro): boolean {
    if (!this.possui(token)) return false;
    this.operation = null;
    return true;
  }

  tokenLeitura(): TokenLeituraTentativa | null {
    const attempt = this.current;
    return attempt ? { lifecycle: this.lifecycle, attemptId: attempt.id, channelId: attempt.channelId, generation: attempt.generation } : null;
  }

  /** Reservation is the only operation allowed to establish a different attempt. */
  reservar(attempt: TentativaNumero, token: TokenOperacaoCadastro): boolean {
    if (!this.possui(token) || token.kind !== 'reserva' || token.attemptId !== null) return false;
    this.current = attempt;
    return true;
  }

  /**
   * Action DTOs may legitimately advance generation/channel while reads may
   * only refresh the exact captured channel generation. In both cases older
   * versions are rejected and the attempt/BU identity must remain stable.
   */
  aplicar(attempt: TentativaNumero, token: TokenOperacaoCadastro, kind: 'acao' | 'retomada'): boolean {
    if (!this.possui(token) || (kind === 'acao' && token.attemptId !== attempt.id)) return false;
    if (kind === 'retomada' && token.kind !== 'retomada') return false;
    const current = this.current;
    if (current && (current.id !== attempt.id || current.buId !== attempt.buId || current.tipo !== attempt.tipo)) return false;
    if (current && (attempt.version < current.version || attempt.generation < current.generation)) return false;
    const authoritativeCancelDetach = kind === 'acao'
      && token.kind === 'acao'
      && attempt.state === 'CANCELLED'
      && attempt.stage === 'CANCELLED'
      && attempt.channelId === null;
    if (current?.channelId && attempt.channelId !== current.channelId && !authoritativeCancelDetach) return false;
    if (current?.state === 'CANCELLED' && attempt.channelId !== current.channelId) return false;
    this.current = attempt;
    return true;
  }

  observar(attempt: TentativaNumero, token: TokenLeituraTentativa): boolean {
    if (token.lifecycle !== this.lifecycle || !this.current || token.attemptId !== this.current.id) return false;
    if (attempt.id !== token.attemptId || attempt.buId !== this.current.buId || attempt.tipo !== this.current.tipo) return false;
    if (attempt.version < this.current.version || attempt.generation < this.current.generation) return false;
    if (attempt.channelId !== token.channelId || attempt.generation !== token.generation) return false;
    if (this.current.channelId && attempt.channelId !== this.current.channelId) return false;
    this.current = attempt;
    return true;
  }

  /** A pair response may advance attemptId only when the real safe BU projection confirms it. */
  adotarPareamento(
    attempt: TentativaNumero,
    token: TokenOperacaoCadastro,
    correlation: { buId: string; channelId: string; attemptId: string; generation: number },
    projection: { buId: string; channelId: string; currentAttemptId?: string | null; generation?: number } | undefined,
  ): boolean {
    if (!this.possui(token) || token.kind !== 'pareamento' || !projection) return false;
    if (token.targetBuId !== correlation.buId || (token.targetChannelId && token.targetChannelId !== correlation.channelId)) return false;
    if (attempt.id !== correlation.attemptId || attempt.buId !== correlation.buId || attempt.tipo !== 'NAO_OFICIAL' || attempt.channelId !== correlation.channelId || attempt.generation !== correlation.generation) return false;
    if (projection.buId !== correlation.buId || projection.channelId !== correlation.channelId || projection.currentAttemptId !== correlation.attemptId || projection.generation !== correlation.generation) return false;
    if (this.current && this.current.buId !== correlation.buId) return false;
    if (this.current?.id === attempt.id && attempt.version < this.current.version) return false;
    this.current = attempt;
    return true;
  }
}
import { FormEvent, useCallback, useEffect, useRef, useState } from 'react';
import { api, BusinessUnit, Eu } from '../api';
import {
  CapacidadesNumero, ChaveIdempotenciaReserva, ConfirmacaoNumeroResponse, chaveIdempotenciaReserva,
  mensagemErroCadastro, motivoCapacidade, nomeConexaoProvedor, nomeEstadoTentativa, OpcoesMeta,
  TentativaNumero, tentativaConfirmada, textoEtapaCadastro, TipoNumero,
} from '../cadastroNumero';
import { DonoCicloCadastro, TokenLeituraTentativa, TokenOperacaoCadastro } from '../cadastroNumero.lifecycle';

declare global {
  interface Window {
    FB?: {
      init(options: { appId: string; version: string; xfbml?: boolean }): void;
      login(callback: (response: FbLoginResponse) => void, options: Record<string, unknown>): void;
    };
  }
}
interface FbLoginResponse { authResponse?: { code?: string }; status?: string }
interface PairResponse { channelId: string; attemptId: string | null; generation: number; pairingEpoch: number; state: string; qrcode: string | null }
interface VerificationResponse { status: string; ownNumberVerified: boolean; receiptVerified: boolean }
interface QrTemporario {
  value: string; buId: string; channelId: string; attemptId: string; generation: number; pairingEpoch: number;
}
const TERMINAL = ['CONNECTED', 'ERROR', 'CANCELLED'];
const adminBu = (bu: BusinessUnit | undefined) => bu?.papel === 'ADMIN' || bu?.papel === 'OWNER';
const statusCanal = (status: string) => ({ CONECTADO: 'Conectado', CONECTANDO: 'Conexão em andamento', DESCONECTADO: 'Desconectado', PENDENTE: 'Pendente' }[status] ?? 'Estado pendente');

/** Guided registration. Secrets and QR values stay only in this mounted component. */
export default function CadastroNumero({ eu, bus, aoAtualizar }: { eu: Eu; bus: BusinessUnit[]; aoAtualizar: (force?: boolean) => Promise<BusinessUnit[]> }) {
  const [open, setOpen] = useState(false);
  const [capacidades, setCapacidades] = useState<CapacidadesNumero | null>(null);
  const [buId, setBuId] = useState('');
  const [novoBu, setNovoBu] = useState(false);
  const [nomeBu, setNomeBu] = useState('');
  const [tipo, setTipo] = useState<TipoNumero>('OFICIAL');
  const [canal, setCanal] = useState<BusinessUnit['channels'][number] | null>(null);
  const [tentativa, setTentativa] = useState<TentativaNumero | null>(null);
  const [opcoes, setOpcoes] = useState<OpcoesMeta | null>(null);
  const [wabaId, setWabaId] = useState('');
  const [numeroId, setNumeroId] = useState('');
  const [cursorUsado, setCursorUsado] = useState<string | undefined>();
  const [pin, setPin] = useState('');
  const [modo, setModo] = useState<'NOVO' | 'JA_REGISTRADO'>('JA_REGISTRADO');
  const [sdkState, setSdkState] = useState<'idle' | 'loading' | 'ready' | 'failed'>('idle');
  const [sdkRetry, setSdkRetry] = useState(0);
  const [qr, setQr] = useState<QrTemporario | null>(null);
  const [pending, setPending] = useState(false);
  const [popupOpen, setPopupOpen] = useState(false);
  const [nonceMissing, setNonceMissing] = useState(false);
  const [erro, setErro] = useState<string | null>(null);
  const [mensagem, setMensagem] = useState<string | null>(null);
  const owner = useRef(new DonoCicloCadastro());
  const lifecycle = useRef(0);
  const attemptRef = useRef<TentativaNumero | null>(null);
  const nonceByAttemptRef = useRef(new Map<string, string>());
  const operationRef = useRef<TokenOperacaoCadastro | null>(null);
  const popupAttemptRef = useRef<{ attemptId: string; token: TokenOperacaoCadastro } | null>(null);
  const optionsAttemptRef = useRef<string | null>(null);
  const reservationKeyRef = useRef<ChaveIdempotenciaReserva | null>(null);
  const fbInit = useRef<string | null>(null);
  const wabaSelectionRef = useRef('');
  const opener = useRef<HTMLButtonElement>(null);
  const heading = useRef<HTMLHeadingElement>(null);
  const wasOpen = useRef(false);

  const clearAttemptUi = useCallback(() => {
    attemptRef.current = null; setTentativa(null); setOpcoes(null); setWabaId(''); setNumeroId('');
    setCursorUsado(undefined); setPin(''); setQr(null); setPopupOpen(false); setNonceMissing(false);
    optionsAttemptRef.current = null; wabaSelectionRef.current = ''; popupAttemptRef.current = null;
  }, []);

  const newLifecycle = useCallback((clearSecrets: boolean) => {
    lifecycle.current = owner.current.invalidar(true);
    operationRef.current = null; setPending(false); clearAttemptUi(); setErro(null); setMensagem(null);
    if (clearSecrets) nonceByAttemptRef.current.clear();
