        const currentChannel = await tx.buChannel.findFirst({ where: { id: context.channelId, currentAttemptId: id, generation: context.generation, operationLeaseToken: channelLeaseToken, operationLeaseUntil: { gt: new Date() } }, select: { receiptVerifiedAt: true, ownNumberVerified: true, verifiedEpoch: true, providerConnectionState: true } });
